from decimal import Decimal, InvalidOperation, localcontext


def sum_measurements(values):
    if not isinstance(values, list):
        raise ValueError("values must be a list")
    parsed = []
    for text in values:
        if not isinstance(text, str):
            raise ValueError("measurements must be strings")
        try:
            value = Decimal(float(text))
        except (ValueError, OverflowError, InvalidOperation) as exc:
            raise ValueError("invalid measurement") from exc
        if not value.is_finite():
            raise ValueError("measurement must be finite")
        parsed.append(value)

    required_precision = max(
        [28] + [len(value.as_tuple().digits) + abs(value.as_tuple().exponent) + 5 for value in parsed]
    )
    with localcontext() as context:
        context.prec = required_precision + len(parsed)
        return sum(parsed, Decimal("0"))
```

